<?php include 'config.php';
if(isset($_POST['pseudo'])){ $_SESSION['pseudo']=$_POST['pseudo']; $_SESSION['uid']=$_POST['uid']; }
if(empty($_SESSION['cart'])) header("Location:/tarifs");
if(isset($_POST['final_order'])){ $stmt=$db->prepare("INSERT INTO orders (pseudo,uid,items,total,pay_id,trans_msg) VALUES (?,?,?,?,?,?)"); $stmt->execute([$_SESSION['pseudo'],$_SESSION['uid'],json_encode($_SESSION['cart']),array_sum(array_column($_SESSION['cart'],'price')),$_POST['pay_id'],$_POST['trans_msg']]); $uid=$_SESSION['uid']; $_SESSION['cart']=[]; header("Location:/historique?uid=$uid&ok=1"); exit; }
$pays=$db->query("SELECT * FROM payments")->fetchAll();?>
