<body class="text-white p-4 max-w-xl mx-auto"><a href="/panier" class="text-xs text-white/40">← Retour</a><form method="post" class="mt-5 space-y-4"><?php foreach($pays as $p):?><label class="glass rounded-xl p-3 flex gap-3 items-center has-[:checked]:border-yellow-400"><input type="radio" name="pay_id" value="<?= $p['id']?>" required><img src="<?= $p['logo']?>" class="w-8 h-8 bg-white rounded-full"><div><p class="text-xs font-bold"><?= $p['nom']?></p><p class="text-[10px] text-white/50"><?= $p['numero']?> - <?= $p['proprio']?></p></div></label><?php endforeach;?><textarea name="trans_msg" required placeholder="Collez message transaction Mvola ici..." class="w-full bg-black border border-white/10 rounded-xl p-3 text-xs h-24"></textarea><button name="final_order" class="w-full bg-yellow-400 text-black rounded-xl py-4 font-black text-xs">ENVOYER COMMANDE</button></form></body></html>